export const workspaceText=(key,language='en')=>WORKSPACE_COPY[key]?.[language==='zh'?1:language==='tw'?2:0]||key;
const paths={cv:'M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h6',profile:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',marketing:'m3 9 16-5v16L3 15zM7 16l2 5h3l-2-5',apply:'M3 7h18v14H3zM8 7V3h8v4M8 13l3 3 6-7'};
export const workspaceIcon=mode=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[mode]||paths.cv}"/></svg>`;
export function workspaceHeader(mode,language='en'){
  const tr=key=>workspaceText(key,language);
  const employer=['marketing','employer','vacancies','talent'].includes(mode);
  const tabs=employer?[['overview','employer'],['jobs','vacancies'],['marketing','marketing'],['talent','talent']]:[['overview','candidate'],['cv','cv-demo'],['profile','talent-profile'],['apply','apply']];
  const active={candidate:'overview',employer:'overview',vacancies:'jobs'}[mode]||mode;
  return `<header class="workspace-heading"><div class="workspace-heading-top"><span class="eyebrow">${tr(employer?'employerWorkspace':'candidateWorkspace')}</span><span class="workspace-demo"><i></i>${tr('demo')}</span></div><h1>${tr(mode+'Title')}</h1><p>${tr(mode+'Body')}</p></header>${employer?'':`<nav class="workspace-navigation" data-workspace-navigation="${employer?'employer':'candidate'}" aria-label="${tr(employer?'employerWorkspace':'candidateWorkspace')}">${tabs.map(([key,view])=>`<button data-view="${view}" ${active===key?'aria-current="page"':''}>${workspaceIcon(key==='overview'?'profile':key==='jobs'?'apply':key==='talent'?'profile':key)}<span>${tr(key)}</span>${active===key?'<i></i>':''}</button>`).join('')}</nav>`}`;
}
